/* stack.h */
typedef struct Stack Stack;   /* opaco: ningún campo visible */
Stack *stack_new(void);
int    stack_push(Stack *s, int x);
int    stack_pop(Stack *s, int *out);

/* stack.c */
struct Stack { int data[100]; int top; };  /* escondido */

function sum(n: number): number {
	if (n === 0) return 0;      // caso base: nada más que sumar
	return n + sum(n - 1);      // paso: un problema más pequeño
}
